-- Run once in the Supabase SQL editor, after 007_session_program.sql.
-- Fills the shared library with the 300 starting exercises (10 per
-- principle and level). Refuses to run if the library already has exercises.

begin;

do $$
begin
  if exists (select 1 from public.exercises) then
    raise exception 'La bibliotheque contient deja des exercices : rien n''a ete ajoute';
  end if;
end;
$$;


commit;
