insert into public.exercises (title, description, category, difficulty, position) values
  ('Geste à vide', 'Sans balle, pieds derrière la ligne de fond : bras de bas en haut, contact imaginaire sous la taille. 3 séries de 10 gestes en vérifiant la position.', 'service', 'debutant', 1),
  ('Service à distance progressive', 'Servir depuis la ligne de cuisine vers la zone en diagonale, puis reculer d''un pas après 5 réussites, jusqu''à la ligne de fond.', 'service', 'debutant', 2),
  ('Service avec rebond (drop serve)', 'Lâcher la balle, la laisser rebondir puis la frapper. Plus simple pour trouver le contact. 20 services, objectif 15 dans la zone.', 'service', 'debutant', 3),
  ('10 services d''affilée', 'Enchaîner 10 services dans la bonne zone. Une faute remet le compteur à zéro.', 'service', 'debutant', 4),
  ('Alterner les côtés', '5 services depuis la droite, 5 depuis la gauche, toujours en diagonale. Vérifier à chaque fois les pieds derrière la ligne.', 'service', 'debutant', 5),
  ('Routine d''avant-service', 'Construire une routine fixe (respiration, rebond de balle, regard sur la cible) et l''appliquer sur 15 services de suite.', 'service', 'debutant', 6),
  ('Annoncer le score', 'Servir en annonçant le score à voix haute (ex. « 0-0-2 »). Le geste et les règles s''apprennent en même temps.', 'service', 'debutant', 7),
